import * as THREE from 'three/webgpu';
import { color, mix, uv, float, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.name = 'brand-mark-wall';
  const pos = config.scenePosition || { x: 0, y: 0, z: 0 };
  const rot = config.scenePosition ? config.scenePosition.rotation : { x: 0, y: 0, z: 0 };
  root.position.set(pos.x || 0, pos.y || 0, pos.z || 0);

  const brandNames = ['HODINKEE', 'MONOCLE', 'WALLPAPER', 'ESQUIRE', 'WIRED', 'FINANCIAL TIMES'];

  const tileW = 1.0;
  const tileH = 0.62;
  const gap = 0.25;
  const gridW = 3 * tileW + 2 * gap;
  const gridH = 2 * tileH + gap;
  const originX = -gridW / 2 + tileW / 2;
  const originY = gridH / 2 - tileH / 2;

  const kicker = createTextMesh({
    text: 'AS FEATURED IN',
    fontAtlas: ctx.fontAtlas,
    fontFamily: 'JetBrains Mono',
    fontWeight: 700,
    fontSize: 9,
    letterSpacing: 0.12,
    lineHeight: 1.2,
    color: '#e8ecf2',
    align: 'center'
  });
  kicker.position.set(0, gridH / 2 + 0.3, 0.01);
  root.add(kicker);

  const tiles = [];
  const timelines = [];

  const tileGeo = new THREE.BoxGeometry(tileW, tileH, 0.06, 1, 1, 1);

  for (let i = 0; i < 6; i++) {
    const row = Math.floor(i / 3);
    const col = i % 3;
    const x = originX + col * (tileW + gap);
    const y = originY - row * (tileH + gap);

    const topColor = color('#1a1a22');
    const bottomColor = color('#121218');
    const vRamp = uv().y;
    const albedo = mix(bottomColor, topColor, vRamp);

    const material = new THREE.MeshPhysicalNodeMaterial();
    material.colorNode = albedo;
    material.roughness = 0.55;
    material.metalness = 0.5;
    material.clearcoat = 0.2;
    material.clearcoatRoughness = 0.3;
    if (material.anisotropy !== undefined) {
      material.anisotropy = 0.6;
      material.anisotropyRotation = 0.0;
    }

    const tileMesh = new THREE.Mesh(tileGeo, material);
    tileMesh.position.set(x, y, 0);
    tileMesh.userData.baseZ = 0;
    tileMesh.userData.baseY = y;

    const wordmarkMat = createTextMesh({
      text: brandNames[i],
      fontAtlas: ctx.fontAtlas,
      fontFamily: 'JetBrains Mono',
      fontWeight: 700,
      fontSize: 13,
      letterSpacing: 0.08,
      lineHeight: 1,
      color: '#e8ecf2',
      opacity: 0.78,
      align: 'center'
    });
    wordmarkMat.position.set(x, y, 0.035);
    root.add(wordmarkMat);

    tileMesh.userData.wordmark = wordmarkMat;
    tiles.push(tileMesh);
    root.add(tileMesh);
  }

  // mount animation: stagger-cards with fade-up
  tiles.forEach((tile, i) => {
    const wordmark = tile.userData.wordmark;
    gsap.set(tile.position, { y: tile.userData.baseY + 0.2 });
    gsap.set(tile.scale, { x: 1, y: 1, z: 1 });
    tile.material.opacity = 1;
    if (wordmark.material) wordmark.material.transparent = true;
    if (wordmark.material) wordmark.material.opacity = 0;

    const tl = gsap.timeline({ delay: i * 0.08 });
    tl.to(tile.position, {
      y: tile.userData.baseY,
      duration: 0.5,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
    }, 0);
    if (wordmark.material) {
      tl.to(wordmark.material, {
        opacity: 0.78,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      }, 0);
    }
    timelines.push(tl);
  });

  // hover interactions per tile
  const hoverTimelines = new Map();

  root.userData.handlers = {
    onPointerMove: (event) => {
      // event expected to carry intersected object info
      const hit = event && event.object;
      tiles.forEach((tile) => {
        const isHover = hit === tile;
        const wordmark = tile.userData.wordmark;
        let tl = hoverTimelines.get(tile);
        if (tl) tl.kill();
        tl = gsap.timeline();
        tl.to(tile.position, {
          z: isHover ? 0.05 : tile.userData.baseZ,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        }, 0);
        if (wordmark.material) {
          tl.to(wordmark.material, {
            opacity: isHover ? 1.0 : 0.78,
            duration: 0.16,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          }, 0);
        }
        hoverTimelines.set(tile, tl);
      });
    },
    onPointerOut: () => {
      tiles.forEach((tile) => {
        const wordmark = tile.userData.wordmark;
        let tl = hoverTimelines.get(tile);
        if (tl) tl.kill();
        tl = gsap.timeline();
        tl.to(tile.position, {
          z: tile.userData.baseZ,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        }, 0);
        if (wordmark.material) {
          tl.to(wordmark.material, {
            opacity: 0.78,
            duration: 0.16,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
          }, 0);
        }
        hoverTimelines.set(tile, tl);
      });
    }
  };

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    hoverTimelines.forEach((tl) => tl.kill());
    hoverTimelines.clear();

    tileGeo.dispose();
    tiles.forEach((tile) => {
      if (tile.material) tile.material.dispose();
      const wm = tile.userData.wordmark;
      if (wm) {
        if (wm.geometry) wm.geometry.dispose();
        if (wm.material) wm.material.dispose();
        root.remove(wm);
      }
      root.remove(tile);
    });

    if (kicker.geometry) kicker.geometry.dispose();
    if (kicker.material) kicker.material.dispose();
    root.remove(kicker);
  };

  return root;
}
